#include "competition/graph/dag_dp.hpp"
int main() {
    init(4); g[1] = {2,3}; g[2] = {4}; g[3] = {4};
    if (!dag_dp(1, 1000000007)) return 1;
    cout << dist[4] << ' ' << ways[4] << '\n'; // 2 2
}

#include "dp/hamilton_path.hpp"
int main() {
    vector<vector<ll>> w(4, vector<ll>(4, HAMILTON_INF));
    w[1][2] = 4; w[2][3] = -1; w[1][3] = 1;
    cout << hamilton_path(w) << '\n'; // 3
}

